Lemma tb_alloc_slot {R} (P : R -> Prop) f : forall st sc req (k : mstate -> Z -> M R) bail mb mk,
  (f <= 64)%nat -> 0 <= sc < 48 -> 0 <= req -> req + IB <= UNIT * size_class sc -> MPOT st f mb mk ->
  KANY P (fun idx => 0 <= idx) k ->
