Lemma tb_bind {A B} (P : A -> Prop) (Q : B -> Prop) : forall (t : M A) (f : A -> M B) cb ck,
  tbound t cb ck P -> 0 <= cb -> 0 <= ck ->
  (forall a cb' ck', P a -> 0 <= cb' -> 0 <= ck' -> tbound (f a) cb' ck' Q) ->
  tbound (sbind t f) cb ck Q.
Proof.
